import { useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Crosshair, Terminal, Monitor, Server, ArrowRight, RefreshCw, Loader2,
  AlertTriangle, CheckCircle2, Shield, Mail, Swords, GitBranch, Eye, Bot,
  ExternalLink, ChevronRight, LayoutGrid, Sparkles, Bug,
} from "lucide-react";
import { RED_TEAM_TOOLS, type RedTeamToolStatus } from "@/lib/redteam/tools";
import { getLabMachines, type LabMachine, type LabMachineId } from "@/lib/redteam/lab";
import { useRedTeamToolStatuses } from "@/hooks/useRedTeamTools";
import { useRedTeamLabConfig } from "@/hooks/useRedTeamLabConfig";
import { FreeSecurityWorkbench } from "@/components/redteam/FreeSecurityWorkbench";
import { BugBountyWorkbench } from "@/components/redteam/BugBountyWorkbench";
import { AutoRedTeamScan } from "@/components/redteam/AutoRedTeamScan";
import { bountyLabUrl } from "@/lib/redteam/bug-bounty-tools";

const ICONS = {
  portal: Crosshair,
  phishing: Mail,
  attack: Swords,
  chain: GitBranch,
  brand: Eye,
  lab: Terminal,
  ai: Bot,
  pentest: Bot,
};

const LAB_ICONS: Record<LabMachineId, typeof Terminal> = {
  kali: Terminal,
  target: Server,
  desktop: Monitor,
  guacamole: LayoutGrid,
  "windows-kvm": Monitor,
};

function statusBadge(status: RedTeamToolStatus | undefined) {
  if (!status || status === "checking") {
    return <Badge variant="outline" className="text-[10px]">Checking…</Badge>;
  }
  if (status === "online") {
    return (
      <Badge variant="outline" className="text-[10px] border-emerald-500/30 text-emerald-400">
        <CheckCircle2 className="h-3 w-3 mr-1 inline" /> Online
      </Badge>
    );
  }
  if (status === "degraded") {
    return (
      <Badge variant="outline" className="text-[10px] border-amber-500/30 text-amber-400">
        <AlertTriangle className="h-3 w-3 mr-1 inline" /> Partial
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-[10px] border-red-500/30 text-red-400">
      Offline
    </Badge>
  );
}

function LabEmbed({ machine }: { machine: LabMachine }) {
  const label =
    machine.embedType === "terminal"
      ? "browser terminal (ttyd)"
      : machine.embedType === "desktop"
        ? "browser desktop (noVNC)"
        : "remote gateway";

  return (
    <div className="rounded-xl border border-rose-500/20 overflow-hidden bg-black">
      <div className="flex items-center justify-between px-3 py-2 border-b border-white/10 bg-zinc-900 text-xs text-zinc-400">
        <span className="flex items-center gap-2">
          <Terminal className="h-3.5 w-3.5 text-rose-400" />
          {machine.name} — {label}
        </span>
        <a href={machine.url} target="_blank" rel="noopener noreferrer" className="text-cyan-400 hover:underline flex items-center gap-1">
          Open full screen <ExternalLink className="h-3 w-3" />
        </a>
      </div>
      {machine.id === "guacamole" && (
        <p className="px-3 py-2 text-xs text-amber-400/90 bg-amber-500/5 border-b border-white/5">
          Login: <strong>guacadmin</strong> / <strong>guacadmin</strong> — add RDP connections to Windows or target hosts
        </p>
      )}
      {machine.id === "windows-kvm" && (
        <p className="px-3 py-2 text-xs text-amber-400/90 bg-amber-500/5 border-b border-white/5">
          Linux + KVM required. First boot installs Windows (~15–30 min). Complete setup in the installer UI.
        </p>
      )}
      <iframe
        title={`${machine.name} lab`}
        src={machine.url}
        className="w-full h-[min(70vh,640px)] bg-black border-0"
        sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-downloads"
        allow="clipboard-read; clipboard-write; fullscreen"
      />
    </div>
  );
}

function LabOfflinePanel({ machine }: { machine: LabMachine }) {
  return (
    <Card className="border-dashed border-amber-500/30 bg-amber-500/5">
      <CardContent className="py-10 text-center space-y-4">
        <AlertTriangle className="h-10 w-10 mx-auto text-amber-400" />
        <div>
          <p className="font-medium">{machine.name} — hosted VM not configured</p>
          <p className="text-sm text-muted-foreground mt-1 max-w-lg mx-auto">
            Use the <strong>Free lab ($0)</strong> tab for CyberChef, cloud shells, and browser tools — no VPS required.
            Hosted Kali/Windows VMs are optional and only appear when an admin deploys them.
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

export default function RedTeamLab() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const practiceTarget = searchParams.get("target")?.trim() || "";
  const vulnHint = searchParams.get("vuln")?.trim() || "";
  const tabParam = searchParams.get("tab");
  const initialTab = tabParam || (practiceTarget || vulnHint ? "bounty" : "auto");
  const { data: labConfig } = useRedTeamLabConfig();
  const { data: statuses, isLoading, refetch, isFetching } = useRedTeamToolStatuses();
  const defaultConfig = {
    labHost: "", flyLabUrl: "", kaliUrl: "", targetUrl: "", desktopUrl: "",
    guacamoleUrl: "", windowsKvmUrl: "", juiceShopUrl: "", dvwaUrl: "",
    mode: "free" as const, source: "none" as const,
  };
  const machines = getLabMachines(labConfig ?? defaultConfig);
  const hasHostedLab = labConfig?.mode === "hosted" && !!(labConfig?.labHost || labConfig?.kaliUrl);
  const [activeLab, setActiveLab] = useState<LabMachineId>("kali");

  const activeMachine = machines.find((m) => m.id === activeLab) ?? machines[0];
  const onlineCount = statuses
    ? Object.values(statuses).filter((s) => s === "online").length
    : 0;

  return (
    <div className="min-h-screen bg-background p-4 md:p-6 space-y-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/30">
            <Crosshair className="h-7 w-7 text-rose-400" />
          </div>
          <div>
            <div className="flex items-center gap-2 text-xs text-muted-foreground mb-1">
              <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
              <ChevronRight className="h-3 w-3" />
              <Link to="/offensive" className="hover:text-rose-400">Red Team</Link>
              <ChevronRight className="h-3 w-3" />
              <span className="text-rose-400">Red Team Lab</span>
            </div>
            <h1 className="text-2xl font-bold text-rose-400">Red Team Lab</h1>
            <p className="text-sm text-muted-foreground">
              Unified pentest sandbox — bug bounty tools, free workbench, optional hosted VMs
            </p>
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
          {isFetching ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
          <span className="ml-2 hidden sm:inline">Refresh</span>
        </Button>
      </div>

      <Card className="border-rose-500/15 bg-gradient-to-r from-rose-500/5 to-orange-500/5">
        <CardContent className="py-4 flex flex-wrap items-center gap-4 text-sm">
          <span className="flex items-center gap-2">
            <Shield className="h-4 w-4 text-rose-400" />
            <span className="font-medium">{RED_TEAM_TOOLS.length} red team tools</span>
          </span>
          {!isLoading && statuses && (
            <span className="text-muted-foreground">
              {onlineCount} online · {Object.values(statuses).filter((s) => s === "degraded").length} partial
            </span>
          )}
          <span className="text-xs text-emerald-400/90 ml-auto">
            Bug bounty lab + $0 cloud shells &amp; CyberChef
          </span>
        </CardContent>
      </Card>

      {practiceTarget && (
        <Card className="border-cyan-500/25 bg-cyan-500/5">
          <CardContent className="py-3 flex flex-wrap items-center gap-3 text-sm">
            <Badge variant="outline" className="border-cyan-500/30 text-cyan-400">Pentest target</Badge>
            <span className="font-mono text-cyan-300">{practiceTarget}</span>
            <span className="text-muted-foreground text-xs flex-1">
              Opened from pentest — use Bug Bounty tab for recon commands, payloads, and scope tracking.
            </span>
            <Button size="sm" variant="outline" asChild>
              <Link to={bountyLabUrl(practiceTarget, vulnHint || undefined)}>Bug Bounty tools</Link>
            </Button>
            <Button size="sm" variant="outline" asChild>
              <Link to={`/offensive/pentest-agent`}>Re-scan</Link>
            </Button>
          </CardContent>
        </Card>
      )}

      <Tabs defaultValue={initialTab}>
        <TabsList className="bg-card/60 border border-border/60 flex flex-wrap h-auto gap-1 p-1">
          <TabsTrigger value="auto" className="gap-1.5">
            <Crosshair className="h-3.5 w-3.5" /> Auto Scan
          </TabsTrigger>
          <TabsTrigger value="bounty" className="gap-1.5">
            <Bug className="h-3.5 w-3.5" /> Bug Bounty
          </TabsTrigger>
          <TabsTrigger value="free" className="gap-1.5">
            <Sparkles className="h-3.5 w-3.5" /> Free lab ($0)
          </TabsTrigger>
          <TabsTrigger value="tools">Tool suite</TabsTrigger>
          {hasHostedLab && <TabsTrigger value="sandbox">Hosted VMs</TabsTrigger>}
        </TabsList>

        <TabsContent value="auto" className="mt-4">
          <AutoRedTeamScan />
        </TabsContent>

        <TabsContent value="bounty" className="mt-4">
          <BugBountyWorkbench
            initialTarget={practiceTarget}
            initialVuln={vulnHint}
            juiceShopUrl={labConfig?.juiceShopUrl || undefined}
            dvwaUrl={labConfig?.dvwaUrl || undefined}
            flyLabUrl={labConfig?.flyLabUrl || undefined}
          />
        </TabsContent>

        <TabsContent value="free" className="mt-4">
          <FreeSecurityWorkbench flyLabUrl={labConfig?.flyLabUrl || undefined} />
        </TabsContent>

        <TabsContent value="tools" className="mt-4">
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 auto-rows-fr">
            {RED_TEAM_TOOLS.map((tool) => {
              const Icon = ICONS[tool.icon];
              return (
                <Card
                  key={tool.id}
                  className="border-border/60 hover:border-rose-500/35 transition-colors cursor-pointer group h-full flex flex-col"
                  onClick={() => navigate(tool.route)}
                  onKeyDown={(e) => e.key === "Enter" && navigate(tool.route)}
                  role="button"
                  tabIndex={0}
                >
                  <CardHeader className="pb-2">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-rose-500/10 border border-rose-500/20">
                        <Icon className="h-5 w-5 text-rose-400" />
                      </div>
                      {statusBadge(statuses?.[tool.id])}
                    </div>
                    <CardTitle className="text-base group-hover:text-rose-300 transition-colors">
                      {tool.label}
                    </CardTitle>
                    <CardDescription className="text-xs">{tool.description}</CardDescription>
                  </CardHeader>
                  <CardContent className="pt-0">
                    <span className="text-xs text-rose-400 flex items-center gap-1">
                      Open tool <ArrowRight className="h-3 w-3 group-hover:translate-x-0.5 transition-transform" />
                    </span>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </TabsContent>

        {hasHostedLab && (
        <TabsContent value="sandbox" className="mt-4 space-y-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
            {machines.map((m) => {
              const Icon = LAB_ICONS[m.id];
              const live = !!m.url;
              return (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => setActiveLab(m.id)}
                  className={`text-left rounded-xl border p-3 transition-all ${
                    activeLab === m.id
                      ? "border-rose-500/50 bg-rose-500/10"
                      : "border-border/60 bg-card/40 hover:border-rose-500/25"
                  }`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <Icon className="h-5 w-5 text-rose-400" />
                    <Badge variant="outline" className={`text-[10px] ${live ? "border-emerald-500/30 text-emerald-400" : "text-muted-foreground"}`}>
                      {live ? "Ready" : "Off"}
                    </Badge>
                  </div>
                  <p className="font-medium text-sm leading-tight">{m.name}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">{m.os}</p>
                </button>
              );
            })}
          </div>

          <Card className="border-rose-500/15">
            <CardHeader className="pb-2">
              <CardTitle className="text-base flex items-center gap-2">
                <Terminal className="h-4 w-4 text-rose-400" />
                {activeMachine.name}
              </CardTitle>
              <CardDescription>
                {activeMachine.description}
                {activeMachine.url && (
                  <span className="block mt-1 font-mono text-[10px]">{activeMachine.url}</span>
                )}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {activeMachine.url ? (
                <LabEmbed machine={activeMachine} />
              ) : (
                <LabOfflinePanel machine={activeMachine} />
              )}
            </CardContent>
          </Card>
        </TabsContent>
        )}
      </Tabs>
    </div>
  );
}
