import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Progress } from "@/components/ui/progress";
import {
  Shield, Play, Loader2, CheckCircle2, AlertTriangle, ShieldAlert,
  Activity, Download, Crosshair,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { usePentestAgent } from "@/hooks/usePentestAgent";
import { exportReportMarkdown } from "@/lib/redteam/pentest-client";
import type { PentestDepth, PentestSeverity } from "@/lib/redteam/pentest-types";

const SEV_STYLE: Record<PentestSeverity, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/40",
  high:     "bg-orange-500/15 text-orange-400 border-orange-500/40",
  medium:   "bg-blue-500/15 text-blue-400 border-blue-500/40",
  low:      "bg-green-500/15 text-green-400 border-green-500/40",
  info:     "bg-slate-500/15 text-slate-400 border-slate-500/40",
};
const GRADE_COLOR: Record<string, string> = {
  A: "text-green-400", B: "text-emerald-400", C: "text-yellow-400", D: "text-orange-400", F: "text-red-400",
};

/**
 * One-click automated red-team scan. After the operator confirms authorization,
 * every tool runs server-side in a single pass (recon → headers → cookies →
 * HTML/secret → CORS → path discovery → CT subdomains → AI summary). No manual
 * tool-by-tool navigation.
 */
export function AutoRedTeamScan() {
  const { toast } = useToast();
  const { scanning, report, error, scan, reset } = usePentestAgent();
  const [url, setUrl] = useState("");
  const [depth, setDepth] = useState<PentestDepth>("standard");
  const [authorized, setAuthorized] = useState(false);

  const run = async () => {
    if (!url.trim()) { toast({ title: "Enter a target URL", variant: "destructive" }); return; }
    if (!authorized) {
      toast({ title: "Authorization required", description: "Confirm you own or have written permission to test this target.", variant: "destructive" });
      return;
    }
    try {
      await scan({ url: url.trim(), depth, authorized, saveEngagement: true });
    } catch (e: any) {
      toast({ title: "Scan failed", description: e?.message ?? "Unknown error", variant: "destructive" });
    }
  };

  const phaseDone = report ? report.phases.filter((p) => p.status === "done").length : 0;
  const phaseTotal = report ? report.phases.length : 8;
  const progress = scanning ? Math.min(90, (phaseDone / phaseTotal) * 100 || 8) : report ? 100 : 0;

  return (
    <div className="space-y-4">
      {/* Control panel */}
      <Card className="bg-[#0a0f1e] border-white/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Crosshair className="h-4 w-4 text-cyan-400" /> Automated Red-Team Scan
          </CardTitle>
          <CardDescription>
            One authorization → every tool runs automatically in a single pass. Non-destructive
            recon only (no exploitation, brute-force, or DoS). Authorized targets you own or have
            written permission to test.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-3 sm:grid-cols-[1fr_auto]">
            <div>
              <Label htmlFor="rt-url" className="text-xs">Target URL</Label>
              <Input id="rt-url" placeholder="https://example.com" value={url}
                onChange={(e) => setUrl(e.target.value)} disabled={scanning}
                onKeyDown={(e) => e.key === "Enter" && run()} className="mt-1" />
            </div>
            <div>
              <Label className="text-xs">Depth</Label>
              <div className="mt-1 flex gap-1">
                {(["quick", "standard", "deep"] as PentestDepth[]).map((d) => (
                  <Button key={d} type="button" size="sm" variant={depth === d ? "default" : "outline"}
                    onClick={() => setDepth(d)} disabled={scanning} className="text-xs capitalize">{d}</Button>
                ))}
              </div>
            </div>
          </div>

          <label className="flex items-start gap-2 text-xs text-muted-foreground cursor-pointer">
            <Checkbox checked={authorized} onCheckedChange={(v) => setAuthorized(!!v)} disabled={scanning} className="mt-0.5" />
            <span>I confirm I <strong>own</strong> this target or have <strong>written authorization</strong> to test it. Unauthorized scanning is illegal.</span>
          </label>

          <div className="flex gap-2">
            <Button onClick={run} disabled={scanning || !authorized} className="bg-gradient-violet-pink text-white shadow-canva">
              {scanning ? <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" /> Scanning…</> : <><Play className="h-4 w-4 mr-1.5" /> Run automated scan</>}
            </Button>
            {report && !scanning && (
              <>
                <Button variant="outline" onClick={() => { const md = exportReportMarkdown(report); const b = new Blob([md], { type: "text/markdown" }); const a = document.createElement("a"); a.href = URL.createObjectURL(b); a.download = `redteam-${report.hostname}.md`; a.click(); }}>
                  <Download className="h-4 w-4 mr-1.5" /> Report
                </Button>
                <Button variant="ghost" onClick={reset}>New scan</Button>
              </>
            )}
          </div>

          {(scanning || report) && <Progress value={progress} className="h-1.5" />}
          {error && <p className="text-sm text-red-400">{error}</p>}
        </CardContent>
      </Card>

      {/* Live phases */}
      {(scanning || report) && (
        <Card className="bg-[#0a0f1e] border-white/10">
          <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Activity className="h-4 w-4 text-cyan-400" /> Pipeline</CardTitle></CardHeader>
          <CardContent className="grid gap-1.5 sm:grid-cols-2">
            {(report?.phases ?? []).map((p) => (
              <div key={p.id} className="flex items-center gap-2 text-xs">
                {p.status === "done" ? <CheckCircle2 className="h-3.5 w-3.5 text-green-400" />
                  : p.status === "error" ? <AlertTriangle className="h-3.5 w-3.5 text-red-400" />
                  : <Loader2 className="h-3.5 w-3.5 text-cyan-400 animate-spin" />}
                <span className="text-slate-300">{p.label}</span>
                {p.detail && <span className="text-slate-500 ml-auto truncate">{p.detail}</span>}
              </div>
            ))}
            {scanning && !report && <p className="text-xs text-muted-foreground">Running all tools…</p>}
          </CardContent>
        </Card>
      )}

      {/* Results */}
      {report && (
        <>
          <Card className="bg-[#0a0f1e] border-white/10">
            <CardContent className="p-5 flex flex-wrap items-center gap-6">
              <div className="text-center">
                <p className="text-xs text-muted-foreground uppercase">Grade</p>
                <p className={`text-4xl font-bold ${GRADE_COLOR[report.grade] ?? "text-slate-300"}`}>{report.grade}</p>
                <p className="text-xs text-muted-foreground">{report.riskScore}/100</p>
              </div>
              <div className="flex gap-2 flex-wrap">
                {(["critical", "high", "medium", "low", "info"] as PentestSeverity[]).map((s) => (
                  <Badge key={s} className={`text-xs border ${SEV_STYLE[s]}`}>{report.metrics[s]} {s}</Badge>
                ))}
              </div>
              <div className="flex-1 min-w-[200px]">
                <p className="text-xs text-muted-foreground mb-1">{report.tools.length} tools ran automatically</p>
                <p className="text-xs text-slate-400">{report.tools.map((t) => t.name).join(" · ")}</p>
              </div>
            </CardContent>
          </Card>

          <Card className="bg-[#0a0f1e] border-white/10">
            <CardHeader className="pb-2"><CardTitle className="text-sm">Executive summary</CardTitle></CardHeader>
            <CardContent><p className="text-sm text-slate-300 leading-relaxed">{report.executiveSummary}</p></CardContent>
          </Card>

          <Card className="bg-[#0a0f1e] border-white/10">
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><ShieldAlert className="h-4 w-4 text-orange-400" /> Findings ({report.findings.length})</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              {report.findings.length === 0 && <p className="text-sm text-muted-foreground">No issues detected by the automated checks.</p>}
              {report.findings.map((f) => (
                <div key={f.id} className="rounded-lg border border-white/10 p-3">
                  <div className="flex items-center gap-2">
                    <Badge className={`text-[10px] border ${SEV_STYLE[f.severity]}`}>{f.severity}</Badge>
                    <span className="text-sm font-medium text-slate-200">{f.title}</span>
                    <span className="ml-auto text-[10px] text-slate-500">{f.tool} · {f.owasp}</span>
                  </div>
                  <p className="text-xs text-slate-400 mt-1.5">{f.description}</p>
                  {f.evidence && <p className="text-[11px] font-mono text-slate-500 mt-1">› {f.evidence}</p>}
                  <p className="text-xs text-cyan-400/80 mt-1"><Shield className="inline h-3 w-3 mr-1" />{f.remediation}</p>
                </div>
              ))}
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}
