function ClientTools() {
  const [input, setInput] = useState("");
  const [sha256, setSha256] = useState("");
  const [sha1, setSha1] = useState("");
  const [jwt, setJwt] = useState("");
  const [jwtOut, setJwtOut] = useState("");
  const [b64in, setB64in] = useState("");
  const [b64out, setB64out] = useState("");

  const runHash = async () => {
    setSha256(await sha256Hex(input));
    setSha1(await sha1Hex(input));
  };

  const runJwt = () => {
    const r = decodeJwtPayload(jwt);
    setJwtOut(r.error ? r.error : JSON.stringify({ header: r.header, payload: r.payload }, null, 2));
  };

  const runB64Enc = () => setB64out(base64Encode(b64in));
  const runB64Dec = () => {
    const r = base64Decode(b64in);
    setB64out(r.ok ? r.value : r.error);
  };

  return (
    <div className="grid gap-4 md:grid-cols-2 auto-rows-fr">
      <Card className="h-full">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm">Hash (browser Web Crypto — live)</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          <Input placeholder="Input text…" value={input} onChange={(e) => setInput(e.target.value)} />
          <Button size="sm" onClick={() => void runHash()} disabled={!input}>Compute SHA-256 / SHA-1</Button>
          {sha256 && (
            <div className="text-xs font-mono space-y-1 break-all">
              <p><span className="text-muted-foreground">SHA-256:</span> {sha256}</p>
              <p><span className="text-muted-foreground">SHA-1:</span> {sha1}</p>
            </div>
          )}
        </CardContent>
      </Card>
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm">JWT decoder (client-side only)</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          <Textarea placeholder="eyJhbG…" value={jwt} onChange={(e) => setJwt(e.target.value)} rows={2} className="font-mono text-xs" />
          <Button size="sm" onClick={runJwt} disabled={!jwt.trim()}>Decode payload</Button>
          {jwtOut && <pre className="text-xs font-mono bg-muted/30 p-2 rounded overflow-auto max-h-40">{jwtOut}</pre>}
        </CardContent>
      </Card>
      <Card className="lg:col-span-2">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm">Base64 encode / decode</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          <Textarea value={b64in} onChange={(e) => setB64in(e.target.value)} rows={2} className="font-mono text-xs" />
          <div className="flex gap-2">
            <Button size="sm" variant="outline" onClick={runB64Enc}>Encode</Button>
            <Button size="sm" variant="outline" onClick={runB64Dec}>Decode</Button>
          </div>
          {b64out && <pre className="text-xs font-mono bg-muted/30 p-2 rounded break-all">{b64out}</pre>}
        </CardContent>
      </Card>
    </div>
  );
}

